import Foundation
final class TranslationStore {
    private let queue = DispatchQueue(
        label: "translations", attributes: .concurrent
    )
    private var rows: [Int: String] = [:]
    func read(id: Int) -> String? { queue.sync { rows[id] } }
    func update(_ text: String, id: Int, done: @escaping () -> Void) {
        queue.async(flags: .barrier) {
            self.rows[id] = text
            DispatchQueue.main.async { done() }
        }
    }
}

После подтверждения update("Дом", id: 2) read(id: 2) даёт «Дом». Callback выражает окончание async-записи.

