    }
    func read(id: Int) -> String? { queue.sync { rows[id] } }
}
func publishCard(done: @escaping () -> Void) {
    let store = PageStore()
    let queue = OperationQueue()
    let prepare = BlockOperation { store.set("Макет", id: 6) }
    let publish = BlockOperation {
        guard let text = store.read(id: 6) else {
            print("Нет готового макета"); return
        }
        print(text)
    }
    publish.addDependency(prepare)
    prepare.cancel()
    publish.completionBlock = { DispatchQueue.main.async { done() } }
    queue.addOperations([publish, prepare], waitUntilFinished: false)
}

Вывод «Нет готового макета», затем done. Finished-зависимость не является доказательством успешного результата.
